/**
 * Config plugin: raise the Gradle JVM memory ceiling.
 *
 * Release builds run `lintVitalAnalyze*`, and Android lint over this app's full
 * module set exhausts the default `MaxMetaspaceSize=512m`, failing the build
 * with `OutOfMemoryError: Metaspace`. Bump the heap and (especially) metaspace
 * so lint has room. Debug builds are unaffected — they don't run lint vital.
 *
 * Applied via gradle.properties because `android/` is regenerated by prebuild
 * (CNG), so editing the generated file directly wouldn't survive.
 */
const { withGradleProperties } = require('expo/config-plugins');

const JVM_ARGS = '-Xmx4096m -XX:MaxMetaspaceSize=2048m';

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (cfg) => {
    const properties = cfg.modResults;
    const key = 'org.gradle.jvmargs';
    const existing = properties.find(
      (item) => item.type === 'property' && item.key === key,
    );

    if (existing) {
      existing.value = JVM_ARGS;
    } else {
      properties.push({ type: 'property', key, value: JVM_ARGS });
    }

    return cfg;
  });
};
